def complete_fixtures() -> list[Path]:
    """Autogenerated models with complete MATLAB output ("Direct p53 effectors" is truncated)."""
    if not AUTOGENERATED.exists():
        return []
    out = []
    for xls in sorted(AUTOGENERATED.rglob("*.xls")):
        stem = xls.with_suffix("")
        if Path(f"{stem}.sif").exists() and Path(f"{stem}_nodeAttributes.txt").exists():
            out.append(xls)
    return out


def fixture_id(path: Path) -> str:
    return path.parent.name


