# --- MATLAB reference
def matlab_act(x: float, w: float, n: float, ec50: float) -> float:
    """Literal transcription of act() in ODE.m."""
    beta = (ec50**n - 1) / (2 * ec50**n - 1)
    K = (beta - 1) ** (1 / n)
    fact = w * (beta * x**n) / (K**n + x**n)
    return w if fact > w else fact


def matlab_rhs(model: netflux.Model, y, w, n, ec50, ymax, tau) -> list[float]:
    """dydt as Netflux2ODE.m builds it."""
    topo = model.topology
    terms = []
    for j, rule in enumerate(topo.rules):
        if not rule.inputs:
            terms.append(w[j])
            continue
        vals = []
        for i, neg in rule.inputs:
            a = matlab_act(y[i], w[j], n[j], ec50[j])
            vals.append(w[j] - a if neg else a)
        if len(vals) == 1:
            terms.append(vals[0])
        else:
            terms.append(0.0 if w[j] == 0 else math.prod(vals) / w[j] ** (len(vals) - 1))
    dydt = []
    for i, producers in enumerate(topo.producers):
        if not producers:
            total = 0.0
        else:
            total = terms[producers[-1]]
            for j in reversed(producers[:-1]):
                total = terms[j] + total - terms[j] * total
        dydt.append((total * ymax[i] - y[i]) / tau[i])
    return dydt


def model_params(model: netflux.Model):
    return (
        [r.weight for r in model.reactions],
        [r.n for r in model.reactions],
        [r.ec50 for r in model.reactions],
        [s.ymax for s in model.species],
        [s.tau for s in model.species],
    )


def native_rhs(model: netflux.Model, y: list[float]) -> list[float]:
    w, n, ec50, ymax, tau = (torch.tensor(v, dtype=torch.float64) for v in model_params(model))
    ode = netflux.NetfluxODE(model.topology, w, n, ec50, ymax, tau)
    return ode(torch.tensor(0.0), torch.tensor(y, dtype=torch.float64)).tolist()
